<script setup lang="ts">
import { computed } from 'vue'
import type { TutorEvent } from '../lib/tutor'
import Icon from './Icon.vue'
import CitationCard from './CitationCard.vue'
const props=defineProps<{events:TutorEvent[]}>()
const entries=computed(()=>props.events.filter(event=>['answer','feedback','finish'].includes(event.type)))
</script>
<template><section v-if="entries.length" class="tutor-transcript"><div class="section-head"><h2>这次学习的足迹</h2><span class="small muted">已提交的回答与反馈</span></div><TransitionGroup name="tutor-entry" tag="div"><article v-for="event in entries" :key="event.id" class="tutor-entry" :class="`tutor-entry-${event.type}`"><template v-if="event.type==='answer'&&event.result"><span class="topic-label">{{event.result.kind==='followup'?'你的理由':'你的作答'}}</span><h3>{{event.result.prompt}}</h3><p class="tutor-answer-text">{{event.result.userAnswer}}</p><p v-if="event.result.correct!==null" class="tutor-result" :class="{incorrect:!event.result.correct}"><Icon :name="event.result.correct?'check':'warning'"/>{{event.result.correct?'本题选择正确':'本题选择与参考答案不符'}}</p><p v-else class="small muted">{{event.result.kind==='followup'?'理由供反思与交流，不自动判分':'简答题请结合参考答案自评，不计入自动得分'}}</p><details v-if="event.result.kind==='question'"><summary>对照参考答案与解析</summary><p>{{event.result.answer}}</p><p class="muted">{{event.result.explanation}}</p><CitationCard v-if="event.result.citation" :citation="event.result.citation"/><p v-else-if="event.result.source" class="source-text">题目附带摘录：{{event.result.source}}</p></details></template><template v-else><span class="topic-label">{{event.type==='finish'?'学习小结':'教练反馈 · 仅供参考'}}</span><p class="tutor-feedback-text">{{event.message}}</p><template v-for="evidence in event.evidence" :key="evidence.evidenceId"><CitationCard v-if="evidence.citation" :citation="evidence.citation"/><blockquote v-else class="tutor-source"><span class="small muted">题目附带摘录 · 无 PDF 原页核验</span><p>{{evidence.quote}}</p></blockquote></template></template></article></TransitionGroup></section></template>
